// Función para generar un color hexadecimal aleatorio
function getRandomColor() {
  var letters = '0123456789ABCDEF';
  var color = '#';
  for (var i = 0; i < 6; i++) {
    color += letters[Math.floor(Math.random() * 16)];
  }
  return color;
}

// Función para generar una lista de colores únicos
function generateUniqueColors(count) {
  var colors = [];
  for (var i = 0; i < count; i++) {
    let newColor;
    do {
      newColor = getRandomColor();
    } while (colors.includes(newColor)); // Asegura que el color no se repita
    colors.push(newColor);
  }
  return colors;
}


// Paleta de colores pastel predefinida
// Puedes añadir más colores a esta lista si tienes muchos segmentos
const pastelColors = [
  '#FFB3BA', // Rosa claro
  '#FFDFBA', // Naranja claro
  '#FFFFBA', // Amarillo claro
  '#BAFFC9', // Verde claro
  '#BAE1FF', // Azul claro
  '#E0BBE4', // Morado claro
  '#FFC0CB', // Rosa pálido
  '#ADD8E6', // Azul cielo
  '#F0E68C', // Caqui claro
  '#98FB98', // Verde menta
  '#DDA0DD', // Ciruela pálido
  '#C9FDD9', // Verde agua
  '#F5DEB3', // Trigo
  '#AFEEEE', // Turquesa pálido
  '#FFDAB9', // Melocotón
  '#E6E6FA', // Lavanda
  '#FDFD96', // Amarillo suave
  '#B0E0E6', // Azul pólvora
  '#D8BFD8', // Cardo
  '#FFE4B5'  // Mocasín
];

// Función para generar una lista de colores únicos de la paleta pastel
function generatePastelColorsFromPalette(count) {
  let colors = [];
  // Usamos el operador módulo (%) para reciclar colores si hay más datos que colores en la paleta
  for (let i = 0; i < count; i++) {
    colors.push(pastelColors[i % pastelColors.length]);
  }
  return colors;
}

jQuery.ajax({
  url: "/solicitud/solicitudTipoxcomuna",
  type: 'GET',
  error: function() {
    // Manejar errores si es necesario
  },
  dataType: 'json',
  success: function(data) {
    var array_NAME_USER = [];
    var array_TOTAL_NOTIFICATIONS = [];
    jQuery.each(data, function(index, value) {
      array_NAME_USER.push(value.COMUNA_NOMBRE);
      array_TOTAL_NOTIFICATIONS.push(value.TOTAL_SOLICITUD);
    });

    // Generar colores pastel únicos basados en la cantidad de datos
    // Si la cantidad de datos es mayor que la paleta, los colores se repetirán de forma cíclica.
    var uniquePastelColors = generatePastelColorsFromPalette(array_NAME_USER.length);

    var ctx = document.getElementById('count_solictudxtiposubsolicitud').getContext('2d');
    var count_solictudxtiposubsolicitud = new Chart(ctx, {
      type: 'pie', // Cambia el tipo a 'pie'
      data: {
        labels: array_NAME_USER,
        datasets: [{
          label: ' Medidores por tipo de Gestiones y Solicitudes de Atención al Ciudadano ',
          data: array_TOTAL_NOTIFICATIONS,
          backgroundColor: uniquePastelColors, // Usa los colores pastel generados
          borderColor: uniquePastelColors, // Usa los mismos colores para el borde para consistencia
          borderWidth: 1
        }]
      },
      options: {
        responsive: true, // Hace que el gráfico sea responsivo al tamaño del contenedor
        maintainAspectRatio: false, // Permite que el gráfico no mantenga la relación de aspecto original
        plugins: {
          legend: {
            labels: {
              font: {
                size: 10 // Reduce el tamaño de la fuente de la leyenda a 10px
              }
            }
          }
        }
        // No se necesita configuración para 'yAxes' en gráficos de pastel
      }
    });
  },
});

